namespace FutureCop.Assets;

/// <summary>
/// Retail terrain tables copied byte-for-byte from SLUS_007.39 (file offset = address -
/// 0x80010000 + 0x800); LevelTerrainTests compares them with the executable when it is present.
/// </summary>
public static class TerrainTables
{
    /// <summary>D_8009AFE8 gVertexIndexTable: four byte offsets (in 8-byte vertex slots) per primitive type.</summary>
    public const uint VertexIndexTableAddress = 0x8009AFE8;

    /// <summary>D_8009B1A4 gTileShapeTable: shape byte per type; func_8006531C copies 0x70 bytes to the scratchpad.</summary>
    public const uint TileShapeTableAddress = 0x8009B1A4;

    /// <summary>Bytes the scratchpad copy of func_8006531C holds (0x1F800000..0x1F80006F).</summary>
    public const int ScratchShapeBytes = 0x70;

    /// <summary>0x200 bytes from D_8009AFE8: all 128 entries (types 111..127 read into D_8009B1A4).</summary>
    public static readonly byte[] VertexIndexBytes = Convert.FromHexString(
        "");

    /// <summary>0x80 bytes from D_8009B1A4.</summary>
    public static readonly byte[] TileShape = Convert.FromHexString(
        "08000800080010181018101810181018080008001810181000080008101810180008000808000800181018100800080010181018000800081018101820202020202020202020204a524a52524a524a6159615959615961332b332b2b332b33443c443c3c443c446b6b74747a817a810000000000010000000400000005000000");

    /// <summary>Entry of D_8009AFE8 for a primitive type (only bits 15..21 of a cell word select it).</summary>
    public static uint VertexIndices(int type) => BitConverter.ToUInt32(VertexIndexBytes, (type & 0x7F) * 4);

    /// <summary>
    /// Byte of the scratchpad shape copy at 0x1F800000 + index (func_80065134). Retail only copies 0x70
    /// bytes; what the scratchpad holds above that is not established, the port answers 0 (like the
    /// harness, whose scratch section is zero-filled). No CONFT cell word reaches that range.
    /// </summary>
    public static byte ScratchShape(int index) => index < ScratchShapeBytes ? TileShape[index] : (byte)0;
}
